import time, functools

def timer(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        t = time.perf_counter()
        result = func(*args, **kwargs)
        print(f"{func.__name__} 用时 {time.perf_counter() - t:.4f}s")
        return result
    return wrapper

@timer
def work():
    sum(i for i in range(100000))

work()

def count_up(n):
    i = 0
    while i < n:
        yield i
        i += 1

for x in count_up(3):
    print(x)              # 0 1 2

def chain(a, b):
    yield from a
    yield from b

print(list(chain([1, 2], [3, 4])))   # [1, 2, 3, 4]

