class Validated:
    def __init__(self, minv):
        self.minv = minv
    def __set_name__(self, owner, name):
        self.name = name
    def __get__(self, obj, owner):
        return obj.__dict__.get(self.name)
    def __set__(self, obj, value):
        if value < self.minv:
            raise ValueError("太小")
        obj.__dict__[self.name] = value

class Account:
    balance = Validated(0)

a = Account()
a.balance = 100

class Registry(type):
    _items = {}
    def __new__(mcs, name, bases, ns):
        cls = super().__new__(mcs, name, bases, ns)
        Registry._items[name] = cls
        return cls

class Plugin(metaclass=Registry):
    pass

class A(Plugin):
    pass

print(list(Registry._items))   # ["Plugin", "A"]

def f(x: int | str) -> int | None:
    if isinstance(x, int):
        return x * 2
    if isinstance(x, str):
        return len(x)
    return None

print(f(3))        # 6
print(f("ab"))     # 2
print(isinstance(5, int | str))   # True
